uint8_t get_key(uint8_t* k, uint8_t len)
{
    int ret;
#ifdef VERBOSE
    uint32_t time;
    print_string("SimpleSerial::get_key command received\n");
    print_string("k: ");
    print_hex(k, len, 0);
    print_string("\n");
#endif
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    /////////////////////// real input masking //////////////////////
    vck_masked_msg_from_seed(mm, k, 0);
#ifdef VERBOSE
    vck_print_msg_shares(mm, "MM");
#endif
    vck_masked_msg_from_seed(mcoins, k, 1);
#ifdef VERBOSE
    vck_print_msg_shares(mcoins, "MCoins");
#endif
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    //////////////////// dummy input masking ////////////////////////
    for (int i = 0; i < len; i++){
        k[i] = 0;
    }
    vck_masked_msg_from_seed(mm_dummy, k, 0);
    vck_masked_msg_from_seed(mcoins_dummy, k, 1);
    memset(mcoins_dummy, 0x0, sizeof(mcoins_dummy));
    memset(mm_dummy, 0x0, sizeof(mm_dummy));
    memset(pk_dummy, 0x0, sizeof(pk_dummy));
    memset(c_dummy, 0x0, sizeof(c_dummy));
    ret = masked_indcpa_enc_cmp(c_dummy, mm_dummy, pk_dummy, mcoins_dummy);
    (void) ret;
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    ////////////////////// initialize modules ///////////////////////
    poly_init_q();
    masked_gadgets_init_q();
    vcu_ntt_lite_reset_state();
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    ////////////////////// const public input ///////////////////////
    for (int i = 0; i < KYBER_INDCPA_BYTES; i++){
        c[i] = 1;
    }
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    /////////////////////////// sleep ///////////////////////////////
    vcu_sleep(SLEEP_LOOP);
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    ////////////////////// trigger and action ///////////////////////
    cw305_trigger_up();
#ifdef VERBOSE
    timer_reset();
    timer_start();
#endif
    ret = masked_indcpa_enc_cmp(c, mm, pk, mcoins);
#ifdef VERBOSE
    time = timer_read();
    print_string("masked_indcpa_enc_cmp time: ");
    print_u32(time);
    print_string("\n\n\n\n");
#endif
    (void) ret;
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    /////////////////////////// sleep ///////////////////////////////
    vcu_sleep(SLEEP_LOOP);
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    /////////////////////////// masked output ///////////////////////
    simpleserial_put('r', 0, NULL);
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////
    /////////////////////////////////////////////////////////////////

    return 0x00;
}


int main(void)
{
    cw305_trigger_down();
    print_string("Kyber CPAPKE Dec\n");

    simpleserial_init();
    simpleserial_addcmd('l', 0, vcu_prng_on);
    simpleserial_addcmd('g', 0, vcu_prng_off);
    simpleserial_addcmd('p', KYBER_SYMBYTES, get_key);

    while(1)
        simpleserial_cw305_rq_get();
}
